<?php
declare(strict_types=1);
require_once __DIR__ . '/Database.php';
function demoId(PDO $pdo,string $sql,array $args): int { $s=$pdo->prepare($sql);$s->execute($args);$id=$s->fetchColumn();if($id===false)throw new RuntimeException('Registro fictício não localizado.');return(int)$id; }
function demoEnsure(PDO $pdo,string $find,array $findArgs,string $insert,array $args): int { $s=$pdo->prepare($find);$s->execute($findArgs);$id=$s->fetchColumn();if($id!==false)return(int)$id;$pdo->prepare($insert)->execute($args);return(int)$pdo->lastInsertId(); }
try {
 $pdo=PDOMysqli::connection();$pdo->beginTransaction();$hash=password_hash('dados-ficticios-apenas',PASSWORD_DEFAULT);
 $users=[];foreach([['Admin Demonstração','admin.demo@asilosoft.local','Administrador'],['Enf. Ana Lima','ana.lima@asilosoft.local','Profissional de Saúde'],['Almox. Bruno Reis','bruno.reis@asilosoft.local','Almoxarife'],['Carla Familiar','carla.familiar@asilosoft.local','Familiar']] as [$n,$e,$p]) $users[$p]=demoEnsure($pdo,'SELECT id FROM usuarios WHERE email=?',[$e],'INSERT INTO usuarios(nome,email,senha_hash,perfil) VALUES(?,?,?,?)',[$n,$e,$hash,$p]);
 $quarto=demoEnsure($pdo,'SELECT id FROM quartos WHERE codigo=?',['A-101'],'INSERT INTO quartos(codigo,capacidade) VALUES(?,?)',['A-101',2]);
 $idoso=demoEnsure($pdo,'SELECT id FROM idosos WHERE identificador=?',['IDOSO-DEMO-001'],'INSERT INTO idosos(nome,cpf,identificador,quarto_id) VALUES(?,?,?,?)',['José da Silva','12345678901','IDOSO-DEMO-001',$quarto]);
 demoEnsure($pdo,'SELECT id FROM idosos WHERE identificador=?',['IDOSO-DEMO-002'],'INSERT INTO idosos(nome,cpf,identificador,quarto_id) VALUES(?,?,?,?)',['Maria Oliveira','98765432100','IDOSO-DEMO-002',$quarto]);
 $familiar=demoEnsure($pdo,'SELECT id FROM familiares WHERE cpf=?',['11122233344'],'INSERT INTO familiares(usuario_id,nome,cpf,telefone,email,parentesco_principal) VALUES(?,?,?,?,?,?)',[$users['Familiar'],'Carla Familiar','11122233344','(11) 99999-0000','carla.familiar@asilosoft.local','Filha']);
 $s=$pdo->prepare('SELECT 1 FROM idosos_familiares WHERE idoso_id=? AND familiar_id=?');$s->execute([$idoso,$familiar]);if(!$s->fetchColumn())$pdo->prepare('INSERT INTO idosos_familiares(idoso_id,familiar_id,parentesco,responsavel_principal) VALUES(?,?,?,1)')->execute([$idoso,$familiar,'Filha']);
 $s=$pdo->prepare('SELECT 1 FROM registros_saude WHERE idoso_id=? AND descricao=?');$s->execute([$idoso,'Registro fictício para desenvolvimento.']);if(!$s->fetchColumn())$pdo->prepare('INSERT INTO registros_saude(idoso_id,usuario_id,descricao,visivel_para_familiar) VALUES(?,?,?,1)')->execute([$idoso,$users['Profissional de Saúde'],'Registro fictício para desenvolvimento.']);
 $material=demoEnsure($pdo,'SELECT id FROM materiais WHERE nome=?',['Luvas descartáveis'],'INSERT INTO materiais(nome,descricao,unidade_medida,estoque_minimo) VALUES(?,?,?,?)',['Luvas descartáveis','Material fictício de demonstração','caixa',2]);
 foreach(['SUS','Plano de Saúde','Instituição'] as $origem){$s=$pdo->prepare("SELECT 1 FROM movimentacoes_estoque WHERE material_id=? AND tipo='Entrada' AND origem=? AND observacao='Entrada fictícia'");$s->execute([$material,$origem]);if(!$s->fetchColumn())$pdo->prepare("INSERT INTO movimentacoes_estoque(material_id,tipo,quantidade,origem,usuario_id,observacao) VALUES(?,'Entrada',10,?,?,?)")->execute([$material,$origem,$users['Almoxarife'],'Entrada fictícia']);}
 $s=$pdo->prepare('SELECT 1 FROM usos_materiais WHERE idoso_id=? AND material_id=? AND observacao=?');$s->execute([$idoso,$material,'Uso fictício']);if(!$s->fetchColumn())$pdo->prepare('INSERT INTO usos_materiais(idoso_id,material_id,usuario_id,quantidade,observacao) VALUES(?,?,?,?,?)')->execute([$idoso,$material,$users['Profissional de Saúde'],1,'Uso fictício']);
 $s=$pdo->prepare('SELECT 1 FROM solicitacoes_compra WHERE material_id=? AND observacao=?');$s->execute([$material,'Solicitação fictícia']);if(!$s->fetchColumn())$pdo->prepare('INSERT INTO solicitacoes_compra(material_id,usuario_solicitante_id,quantidade,observacao) VALUES(?,?,?,?)')->execute([$material,$users['Almoxarife'],20,'Solicitação fictícia']);
 $pdo->commit();echo "Dados fictícios inseridos ou reutilizados com sucesso.\n";
} catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,"Seed fictício falhou: {$e->getMessage()}\n");exit(1);}
